 "headline": "宽厚持重十余年，一次跪接天书",
 "lead": "王旦字子明，大名莘县人，父王祜为宋初名臣，家世清显。少沉静好学，太平兴国五年中进士，释褐大理评事，出知平江府，以清慎称。真宗即位后历知制诰、参知政事，景德三年以同平章事居首辅，居相位十余年，宽厚持重，未尝以私害公，朝野称之。同榜进士张咏论一时人物，说他深沉有德、镇服天下，与李沆、寇准并举为最。大中祥符元年，真宗倡天书封禅，王旦身为首相不能谏止，反而先接过天书跪奉给皇帝，只在支应细处求少扰百姓，论者以为惜。天禧元年薨于位，享年六十一，赠太师，谥文正，遗表请召还寇准，真宗叹其忠。晚年自悔天书之事，遗令薄葬，不受赠赙；子弟多不预政，其子王素后来以直谏显名。宋人称他为太平宰相，这称呼里有敬，也留着一点保留。",
