 "headline": "三黜三光：越贬越亮的参知政事",
 "lead": "范仲淹字希文，苏州吴县人，祖籍邠州。父范墉早卒，母谢氏改嫁淄州朱氏，仲淹随继父姓朱，名说。少年读书应天府书院，日煮粥一器，划为四块，早晚各食其二。大中祥符八年登进士第，入仕之后才奏请复姓归宗。天圣间监泰州西溪盐仓，倡议修筑捍海堰，绵亘近五百里，民称范公堤。天圣七年上疏请章献太后还政，贬为河中府通判；明道二年又与孔道辅率台谏谏废郭皇后，贬知睦州；景祐三年上《百官图》讥吕夷简用人，被指朋党，贬知饶州。三次被逐出京城，士林称为三黜三光，说他一次比一次走得远，名声也一次比一次亮。康定元年西夏犯边，他被起用知延州，修城寨、募土兵，与韩琦并称韩范；庆历三年入朝为参知政事，条上十事，行庆历新政，二年而罢。皇祐四年卒于徐州，年六十四，谥文正，仁宗亲书碑额。",
