 "headline": "不持一砚的知县，做到开封府的黑脸",
 "lead": "包拯字希仁，庐州合肥人，少以孝闻。天圣五年登进士第，那一科人才鼎盛，号称宰执榜，同榜有王尧臣、韩琦、赵概，榜下还有文彦博。初授建昌知县，他以亲老辞不赴，回家奉养父母近十年，父母相继去世，庐墓终丧仍不忍去。后知天长县，有盗割人牛舌者来告，他令其回家杀牛卖肉，不久便有人来告私宰，割舌之盗由此落网。庆历元年知端州，端砚为贡品，前任太守多取以馈权贵，他岁满不持一砚归。庆历三年为监察御史，由御史台长官王拱辰推荐，上任之后力论新政之弊，又请罢内降、抑侥幸。皇祐间历知瀛州、扬州，迁江宁府；嘉祐元年权知开封府，立朝堂、开正门，讼者直造庭下，贵戚为之敛手。嘉祐四年为御史中丞，弹劾不避权贵，攻张尧佐最力。嘉祐六年拜枢密副使，未及大用，朝野已望其为相。嘉祐七年卒，年六十四，谥孝肃，京师吏民叹息，后世遂以之为清官之范。",
