   "a": "仁宗朝的问题不在没人看出弊病，而在没人肯动制度。仁宗晚年多病，宫中又有立储的暗流，满朝旧臣讲的是守成，一篇主张改法度的长疏递上去，只能束之高阁，不会有人替它说话。神宗不同：他二十岁即位，面对的是空了的国库和给西夏的岁币，旧臣能给的仍是祖宗之法不可变这一句，他要的是一个敢把话说到底、又肯替他背骂名的人。王安石的资历恰好齐全：进士高第、十余年州县实政、屡召不起的清名，再加上韩维在讲席上多年替他传话。人还是那个人，听的人换了，位置也就换了。",
