 "headline": "新法半出其手，反复之名亦由此起",
 "lead": "吕惠卿字吉甫，泉州晋江人，父吕璹为官，出身官吏世家。嘉祐二年他登进士第，授真州推官，入京后与王安石论经义，谈得投机，就此进入变法集团。熙宁二年制置三司条例司设立，他为检详文字，青苗、免役、均输诸法的条贯多出其手，时人称护法善神。熙宁七年王安石罢相，他拜参知政事，续行新法，创手实法以括民财，务为严苛以自固；又与王安石争权，发其私书，二人交绝，神宗亦薄其为人。元祐间旧党当国，他被指为奸邪，责授建宁军节度副使，建州安置，不得签书公事。绍圣元年哲宗亲政，新党复起，他以观文殿学士知延安府，修城寨、御西夏，边人称其能。崇宁间蔡京当国，借党籍之名排击异己，他也在其中，再贬安置；政和元年卒，年八十。新法之实半出吕氏之手，反复之名亦由此起，后世修史者把他列进奸臣传。",
