    "q": "为什么他在御前能驳倒司马光，却挡不住刻深的名声？",
    "a": "因为辩论赢的是道理，名声输的是执行。御前那一场，他手里有具体的账：二分取息比起豪族的倍称之息确实轻，官仓有谷也是事实，司马光讲的是州县抑配的可能，他讲的是条文的本意，皇帝自然听得进他。可条文到了州县，抑配就真的发生了，追呼也确实扰民，而这些账最后都记在写条文的人身上。他越把条贯写得细密，执行时的硬指标越难回避，刻深二字就越洗不掉。这不是他被冤枉，而是他把自己的名字写进了每一条法里。",
