 "headline": "两边都站过的执政，两边都不容他",
 "lead": "曾布字子宣，建昌军南丰人，兄曾巩以文章名世，为唐宋八大家之一。嘉祐二年兄弟同登进士，曾布初授宣州司户参军，熙宁初为王安石所擢，参与新法条拟，与吕惠卿共事，后因论市易扰民与当国者相左，出知饶州。元祐初旧党当国，他倒向司马光一边，助废免役，却又力争不可尽废，遂与旧党亦不合。绍圣间章惇当国，他被引入枢府，同主绍述，然两人争权日甚，章疏往来不绝。元符三年哲宗崩，立嗣之议起，他转而附向太后，拥立端王，等于当众拆了章惇的台。徽宗即位，曾布拜尚书右仆射，与韩忠彦并相，改元建中靖国，想在新旧两党之间求一个折中。崇宁元年蔡京入朝，先与他联手挤走韩忠彦，转手就把他贬到江南，再贬岭南。大观元年卒于贬所，年七十二，谥文肃。他一生以政术显，不以名节称，史家对他反复于两党之间的讥评，至今未息。",
