 "lead": "李纲字伯纪，邵武军人，祖籍无锡，父李夔为官，家世仕宦。政和二年登进士，授镇江教授，宣和间为太常少卿，因论水灾触忤蔡京，被贬监沙县税。靖康元年金兵渡河围汴，他为亲征行营使，登城督战，募壮士缒城击敌，又在水门以长钩、大石击沉金军火船，力却金军；旋为主和者所排而罢，太学生陈东率众伏阙呼号，朝廷不得已复其职。建炎元年高宗即位于应天，起他为尚书右仆射兼中书侍郎，他条陈十事，主张罢和议、修战守、还都汴京，并置河北招抚司、河东经制司联络两河义军，派宗泽去开封收拾残城。黄潜善、汪伯彦与他议事辄相左，七十余日而罢相。此后绍兴年间屡起屡罢，多授宫观、州郡之职而不予兵权，建炎三年更落职责居鄂州、移澧州。绍兴十年卒，年五十八，赠少师，谥忠定。朱熹论南渡人物，推他为第一，称其孤忠尽瘁、死而后已；他所论水灾、和战的诸疏，也被后人视为可为后世法。他一生的判断多被后来的事实证实，人却始终没有被真正放回中书。",
