 "headline": "两场大败之间，二十年的主战招牌",
 "lead": "张浚字德远，汉州绵竹人，父张咸以进士起家。政和八年登进士，调山南府掾，靖康间累迁太常少卿，金人逼京，他力言不可割三镇，与主和者不合。建炎三年苗傅、刘正彦作乱，逼高宗禅位，张浚时以礼部侍郎在平江，移书诸镇，约韩世忠、张俊、刘光世勤王，事平后入朝，自礼部侍郎一跃而知枢密院事，成为南宋军方名义上的第一人。建炎四年督川陕诸军，调五路兵与金军决战于富平，诸军不相统属，一败而陕西尽失，他退保川口，上表自劾，罢为提举江州太平观，居福州。绍兴四年金与伪齐南侵，起复知枢密院事，五年除都督诸路军马，置司镇江，节制岳飞、韩世忠诸军，兵权向中枢收拢。绍兴七年他罢刘光世之兵，处置失当，郦琼挟四万人叛降伪齐，是为淮西兵变，他自请罢相，出判福州。此后长期不复大用，直到绍兴三十一年金主亮南侵，复起判建康府，收拾江防。隆兴元年孝宗锐意恢复，他督师江淮主持北伐，李显忠、邵宏渊二将争功，大军溃于符离，再罢都督，出判福州。隆兴二年病卒，年六十八，谥忠献。其子张栻为理学大家，开南轩一派。他一生主战而不度力，富平、符离两败，论者以为志大才疏；然川陕人心归之，朝廷每逢边事吃紧，第一个想起的仍旧是他。",
