   "a": "因为南宋初年最缺的不是能打的人，是能替朝廷管住能打的人。诸大将各拥家兵，皇帝要有人在中间调度，又不能让这个人真有独立于皇权的本钱。张浚恰好合用：文臣出身，主战的名声足够响，两次败仗又让他的声望始终不满，威胁不到皇权。他每次起复，都伴随着一次边警与一次对主和派的压力。败也罢，罢也罢，只要边事还在，这个位子就总有人要替他留着。",
