 "headline": "主战而不废和议，最后饿死在海南",
 "lead": "赵鼎字元镇，解州闻喜人，幼孤，苦学，崇宁五年登进士第，历州县有声。靖康间为开封士曹，金人立张邦昌，他与胡寅等逃匿山中，拒不称臣，士论高之。建炎间为御史中丞，连章劾黄潜善、汪伯彦误国之罪，二人遂罢，他由此以敢言知名。绍兴四年拜尚书左仆射、同中书门下平章事，兼知枢密院事，荐岳飞于行伍、拔韩世忠于偏裨，力主迎战而不废和议，朝政稍振。绍兴八年，秦桧主屈己议和，金使至临安称诏，他在御前力争，谓不可屈膝事仇，遂罢相出知绍兴。绍兴十年再贬潮州，绍兴十四年移吉阳军，渡海至海南岛南端。绍兴十七年，他自知秦桧必不肯放，自书铭旌「身骑箕尾归天上，气作山河壮本朝」，绝食而死，年六十三。孝宗朝追谥忠简，配享高宗庙庭。他为相以恢复为志，去位以和议为罪，一生所争的那个次序，恰是南宋此后二十年不再讨论的问题。",
 "points": [
  "转折一：靖康间拒附张邦昌，建炎间以御史中丞连章劾去黄潜善、汪伯彦，以气节与敢言立名于南渡之初。",
  "转折二：绍兴四年拜相兼知枢密院事，荐岳飞、拔韩世忠，力主亲征而不废和议，成为主战一派在朝中的主持者。",
  "转折三：绍兴八年与秦桧争屈己议和而罢相，此后一贬潮州、再贬吉阳军，绍兴十七年绝食死于海南。"
 ],
 "why": [
  {
   "q": "为什么南渡初年的宰相之位，会落到赵鼎这样一个既主战又不废和议的人头上？",
   "a": "因为那几年朝廷试过的人都不合用。黄潜善、汪伯彦主和误国，被台谏劾走；吕颐浩能办事却压不住诸将；朱胜非在位日短。赵鼎的履历刚好补齐了缺口：靖康间拒附张邦昌，建炎间做御史中丞连章劾去两个误国宰相，名声在清议一边；他又是进士出身的州县官，懂钱粮与人事。更要紧的是他不走极端，主战而不废和议，皇帝既要摆出打的姿态，又不想真把和路断掉，用他最省事。相位看似论功，其实是各方都能接受的折中。",
   "basis": {
    "type": "book",
    "text": "《如果这是宋史》第三十章 冠绝天下"
   }
  },
  {
   "q": "为什么他一生主战，却始终不肯把和议的门彻底关死？",
   "a": "因为他要的是次序，不是姿态。南渡之初国力未复，诸大将各拥家兵，一战而败则江防尽失，他主张先固江防、核财赋、整军伍，等有了本钱再谈恢复；和议在他看来是可以拖时间的手段，不是国是。这与秦桧的屈己称臣差得很远——他反对的是跪着接诏，不是反对谈判。也正因这一层，他在主战与主和两边都不算自己人：主战者嫌他持重，主和者嫌他碍事。绍兴八年他一倒，折中的路就断了，朝廷只剩下跪与不跪两条。",
   "basis": {
    "type": "book",
    "text": "《如果这是宋史》第二章 沉默的铠甲"
   }
  }
 ],
