 "headline": "两度定策，一辈子劝皇帝不要打",
 "lead": "史浩字直翁，明州鄞县人，崇宁五年生。少笃学，绍兴十五年登进士第，为温州教授，后入为太学正，以讲学得士心。孝宗为普安郡王、建王时，他在王府讲书，是潜邸旧臣；绍兴三十二年高宗内禅，史浩定策立赵昚，由讲官骤至执政。隆兴元年张浚请举北伐，他力言兵未可动，与张浚议不合，罢相出知绍兴府，此后闲废二十余年。淳熙十六年孝宗内禅，史浩再相，参预光宗嗣位，又持议阻废李凤娘，虽老而不肯依违。绍熙五年卒，年八十九，谥文惠。其子史弥远后为宁宗、理宗两朝权相。后人论他持重守成，是孝宗朝的老成人；也有人说他两次挡下用兵与废立，看似周全，实则把南宋那一点锐气一并挡在门外。",
