    "q": "为什么韩侂胄能赶走一位刚立了大功的宰相？",
    "a": "因为他用的不是兵，是言路与宫禁。宰相的权力在政事堂，台谏的权力在章疏，韩侂胄掌握了后者，就等于掌握了朝廷的舆论。赵汝愚是宗室，这个身份平时是资望，到了被攻击时就成了把柄：一句将以宗室不利于社稷，足以让宁宗心里发凉。加上宁宗的皇位本是别人替他定下的，他本能地不愿见到一个太强的宰相。韩侂胄只是顺着这两处疑心推了一把。",
