    "q": "为什么韩侂胄要在当国之初发动一场针对士人的党禁？",
    "a": "因为他的权位来路不正，需要一场清洗来补。他是外戚，以门荫入官，没有科第的清望；定策之功又分不到他名下，宰执之位是靠排挤赵汝愚得来的。这样的人最难压住的不是武将，是士论。赵汝愚一党多在道学门下，把他们的学问判成伪学，等于把政敌的资格一并取消：既不能应举，也不能居官，连学生都要避讳。党禁对他是一举两得，对士林却是一刀几十年。",
