    "q": "为什么襄阳被围多年，临安朝廷竟然无人敢言？",
    "a": "因为边报的通道捏在宰相手里，而宰相的权威又建立在「边事无碍」这四个字上。贾似道专国政十五年，台谏皆其私人，言者辄斥；他一旦承认襄阳危急，就等于承认自己十五年的措置全错。度宗要的是宫中无事，只要宰相说无碍，他就不问。于是一道道求援文书在中书停下，援兵与粮械也跟着停下，直到皇帝自己开口问起，局面已经无法挽回。底本把这一节写得很轻，只用一句「听说襄阳已经被蒙古人围困好多年了」，越轻越见其重。",
