 "headline": "行伍出身做到枢密使，因猜忌出判",
 "lead": "狄青，字汉臣，汾州西河人，家世农家，行伍出身，善骑射。宝元、康定间从军西陲，与西夏战凡二十五战，中矢八次，每战披发铜面，夏人畏之如神。庆历间为泾原路副都总管，范仲淹见而奇之，授以《左氏春秋》，说为将者不知古今战例只是一勇之夫；狄青折节读书，遂通古今兵法，尹洙也曾把他推荐给范仲淹与韩琦。皇祐四年，侬智高反于广源州，连破邕、浔诸州，岭南震动；狄青上表请行，仁宗壮之，授宣徽南院使、宣抚荆湖南北路。皇祐五年上元夜，他潜渡昆仑关，一战破侬智高，岭南平。以功拜枢密使，武人入枢府，台谏纷纷论其非故事；嘉祐元年出判陈州，次年卒，年五十，谥武襄，仁宗为之辍朝。宋人以武人入枢府为异数，狄青之罢，实由猜忌。",
