   "a": "因为北宋的枢密院例由文臣主之，武臣入枢府被视为异数。他以平岭南之功拜枢密使，台谏立刻以非故事相攻——这不是弹劾某一件错事，是排斥一种身份。仁宗要用其功，却挡不住清议；嘉祐元年他被出判陈州，次年卒于任所。底本说得直白：宋人以武人入枢府为异数，狄青之罢，实由猜忌。他没有罪名，所以也就无从自辩；这也正是他与岳飞被后人并提的原因。",
