    "a": "因为他触的不是军务，是国策与官制两条线。宋制重文武之分，武臣议论朝廷大计即属越职言事，一个低级军校上书数千言请皇帝亲征，形式上就是僭越。更要紧的是内容：新君刚在应天站住脚，最不愿被人提起的就是迎回二帝。他的话在道理上不错，在朝局上却正好踩在最痛的地方。夺官既是对他的处分，也是给全军看的一个样子：北进之议，不由武人来说。",
