   "a": "因为这件事对他有好处，而他也没有拒绝的余地。收兵权之后三大将的私兵改成御前诸军，他虽首倡纳兵而保住权位，可手里的兵已经没了；要在这套新朝局里继续站住，只能靠替宰执办事。他又与岳飞自讨李成时便有纠葛，鄂州旧部是诸军中最完整的一支，不拆这一支，其余都不算收干净。办成之后他封清河郡王，富贵甲于诸将；办不成，他就是下一个被拆的人。",
