   "a": "因为他把战场从隘口挪到了山原上。宋军在西线打的是骑战与平地会战，富平五路合兵仍败，说明这条路走不通；吴玠退到和尚原，据高而守，用强弓迭射抵掉金军骑兵的冲阵之长，又先派人下秦岭抢了三十万斛粮，让这支残兵有饭吃。金军要入蜀只有几条秦岭孔道，道窄而险，兵力展不开，他的兵虽少也能守住。地势、粮、箭，三样凑齐，才有了以少胜多的可能。",
