    "余玠经略四川时遍求可用之人，王坚与张钰等一同被选中。",
    "宝祐二年，王坚知合州，做的第一件事是移州治。",
    "他把州治迁到钓鱼山上，凭山临江，三面环水，形势自成。",
    "山上修城凿池，池可养鱼，城可屯粮。",
    "他又招集诸军、积粮练兵，作长期坚守的打算。",
    "底本说钓鱼城未战之前，先是一座能自己活下去的城。"
