    "a": "因为余玠要的是能经营、能久守的人，不是能打一仗的人。四川当时无险可守，蒙古军一来，州县就把粮秣人口丢在平原上，所以改行山城之法，把州治搬上山。王坚积功至都统制，以勇略知名，又是余玠在川中精心搜求到的几个人之一；他到合州之后先移州治、再修城凿池、积粮练兵，做的正是这套办法。底本还记孟珙在荆湖烧粮毁船，派去具体实施的人就是他——能办事、能守城，余玠才敢把蜀口交给他。",
