    "a": "因为他把船绑在了一起，也把自己绑住了。德祐元年他率舟师入卫临安，与刘师勇、孙虎臣以万余艘战船横遮江面，约李庭芝出瓜洲、张彦出常州三路夹击；结果两家失约不到，他成了一旅孤军，仍用连舟结阵之法迎敌。元将阿术纵火攻之，舟阵一乱便无法散开，死者甚众。底本记他四年前只把十艘船连成一舫，这回是一千多艘绑成一座大城——阵越密，火越省事。这不是勇气不足，是战法只备了守，没备退。",
