   "q": "为什么李庭芝守扬州数年，最终还是守不住？",
   "a": "因为扬州的存亡不取决于一城之力。德祐以后两淮诸州相继而降，扬州的粮道与援路都被切断；张世杰在焦山约他出瓜洲夹击，他未能如约，江北就再没有一支能策应的兵。他能做的只是闭城死守、出兵袭扰，把元军拖在城下。城里的粮一天少一天，副手朱焕在他出走之后以城降元，泰州也随即被围。底本说他聪明、早知纯粹的军人出身主持不了一方，而他的理想终究没能实现——这句说的正是他：能守一城，改不了全局。",
