MR.people["song:lideming"] = {
 "headline": "受宋辽两册而阴蓄国力的夏王",
 "lead": "李德明，党项银州之族，父李继迁以抗宋起家，他自幼随父在军中，见惯了兵事与帐前的讨价还价。景德元年李继迁中流矢而死，德明嗣为定难军留后，刚接手就遇上一场乱子：吐蕃人潘罗支卷土重来，党项人竭尽全力才保着他逃回灵州城。他没有接着硬打，而是遣使入宋请和；景德二年宋以定难节钺授之，封西平王，岁给俸赐，沿边重开榷场。此后二十余年，他一面在宋称臣、一面受辽封册，辽人待他如外孙，还追封其父李继迁为尚书令。他把力气转到河西，攻回鹘、取甘州凉州；天禧四年派大臣贺承珍北渡黄河，在怀远县营城阙宫殿宗社籍田，迁居兴州，为西夏建都立下根基。宋夏休息近三十年，明道元年病殁，年五十一，子元昊嗣位。父亲打下的是一块能立国的地，他留给儿子的是一套能立国的家当。",
 "points": [
  "受命：父死嗣为留后，先被吐蕃人赶回灵州城，转手便向宋朝请和止战。",
  "施政：一面向宋称臣受节钺，一面向辽受封夏国王，两受封册而暗中自强。",
  "奠基：取河西、营兴州，宫室官属皆备，死后子元昊遂以之为帝业之本。"
 ],
 "why": [
  {
   "q": "为什么李德明甘愿向宋辽两国同时称臣？",
   "a": "因为他要的不是名号，是时间。父亲李继迁二十年里打了无数仗，党项拿到的只是灵州一城与满地的敌手；他一接手就明白，再打下去，先断的是自己的家底。向宋称臣，换来节钺、俸赐与沿边榷场，边地的粮食与货物就能进来；向辽受封，换来一个可以对宋朝示威的靠山，辽人待他如外孙，还追封其父。两边都称臣，两边都不必真交出兵权。底本说宋辽各自都以为把他笼络住了，实际上他只是把战场从草原换到了河西与工地上。",
   "basis": {
    "type": "book",
    "text": "底本第十七章 李继迁时刻"
   }
  }
 ],
 "gap": [
  "李德明受宋封西平王时的册文，底本未载",
  "他攻取甘州、凉州的具体年份，诸书所记不一",
  "兴州营建时的城制规模，史无明文",
  "他病殁于何月，底本未详"
 ],
 "quotes": []
};
