MR.people["song:abaoji"] = {
 "headline": "统一八部、依汉例称帝的契丹太祖",
 "lead": "耶律阿保机，契丹迭剌部人，祖与父皆为夷离堇，是八部之中专掌征伐的那一支。唐咸通十三年他出生时，契丹还只是草原上一股随波逐流的势力，所有的努力都只为温饱与安全；到他手里，八部被并成一处。唐末他继为迭剌部夷离堇，连破室韦、奚、乌古，部众归心；后梁开平元年即可汗位，却不肯照祖宗三年一换的旧规让位，诸弟与七部酋长因此两次发难。他用汉人韩知古、康默记、韩延徽，营城郭、定赋税、立亲兵卫队，把可汗的帐幕改成了朝廷。贞明二年，他依汉例正式建国称帝，国号契丹，建元神册，都上京临潢；此后又命人创制契丹大字，西征突厥、吐谷浑，东灭渤海，改其地为东丹国，以长子耶律倍主之。天显元年班师至扶余府而卒，年五十五，庙号太祖，次子德光继位。辽之制度由此立：南面官治汉人，北面官治部族。",
 "points": [
  "起家：迭剌部世为夷离堇，他以征伐立威，连破室韦、奚、乌古，部众归之。",
  "建制：即可汗位而不肯三年一让，用汉人营城郭、定赋税、立亲兵，把帐幕变成朝廷。",
  "开国：依汉例称帝建契丹，创文字、灭渤海，死于班师途中，辽制自此而定。"
 ],
 "why": [
  {
   "q": "为什么阿保机能从八部之一的夷离堇做到一国之主？",
   "a": "因为他把三件事一起做了：打仗、用人、改制。打仗让他有战利品可分，部众才肯跟着他；用人让他不必只靠族人，韩知古、康默记是被抢来的，韩延徽是被强留下来的，三个人替他营城郭、定赋税、立仪制；改制则让他有理由不交权——三年一换可汗是祖宗的旧规，他的弟弟们正是顺位最靠前的替换者，所以他必须先让自己不可替换。底本说契丹此前只是历史长河里一颗随波逐流的小沙粒，到了他这一代才聚成一块石头。",
   "basis": {
    "type": "book",
    "text": "底本第四章 如果这是契丹"
   }
  }
 ],
 "gap": [
  "阿保机出生的月日，底本未载",
  "契丹大字创制的具体经过，史无明文",
  "西征突厥、吐谷浑的年份，诸书所记不一"
 ],
 "quotes": []
};
