 "headline": "从皇后到摄政：澶渊城下的辽国女主",
 "lead": "萧绰，小字燕燕，辽北院枢密使萧思温之女，出身后族。应历间入宫，保宁元年辽景宗即位，立她为皇后。景宗自幼在火神淀兵变中受惊，体弱多病，连皇帝的日常工作都难以完成，国事多决于皇后；她由此在景宗一朝就摸熟了兵、民、财三件事。乾亨四年景宗崩，圣宗年十二即位，她以太后之尊摄政，哭着问群臣「母寡子弱，族属雄强」该怎么办，耶律斜轸答以「信任臣等」，她又把宿卫交给韩德让，军政一把抓。统和四年宋雍熙北伐三路来攻，她全族动员、亲督诸军，破曹彬于岐沟关，又俘杨业于陈家谷。统和十七年发大军南征，统和二十二年与圣宗亲率大军南下，抵澶州，与宋订澶渊之盟，岁得银绢三十万。此后宋辽百余年无边警，论者多归其力。统和二十七年崩于行帐，年五十七，谥承天太后。太后当国二十七年，辽由中衰而复振，韩德让亦以顾命之重终始不衰。",
