 "headline": "从鄂州撤兵到崖山灭宋的二十年",
 "lead": "忽必烈，拖雷第四子，宪宗蒙哥之弟，母唆鲁禾帖尼。同母兄弟四人，蒙哥是蒙古共主，旭烈兀西征建立伊儿汗国，阿里不哥守着漠北的千户，他是其中最肯读汉人书的一个。受命经略漠南后开府金莲川，用刘秉忠、姚枢等汉儒，立邢州、开屯田，汉地的赋税与人才渐渐聚到他的幕府，也因此招来蒙哥的核查。宝祐元年率军自临洮南下，渡金沙江灭大理，云南遂入蒙古。开庆元年蒙哥死于钓鱼城，他已进至鄂州江北，闻讯许贾似道议和北还；中统元年即大汗位于开平，与阿里不哥争位四年乃定。至元八年取《易经》大哉乾元之义建国号大元，定都大都，立中书省、行省、御史台；至元十三年伯颜入临安，谢太后奉表出降，十六年崖山海战，宋祚遂终。至元三十一年卒，年八十，庙号世祖。",
