    "太原之役的将士等着赏格，久不见下，营中已有怨言。",
    "德昭进宫，为这些人请赏。",
    "底本写他请功时，旁人都觉得这是投桃报李、礼尚往来。",
    "太宗回他一句：待汝自为之。",
    "这句话的意思是，等你做了皇帝再赏他们不迟。",
    "德昭退下，回去之后既不申辩，也没有托人转圜。",
    "他取刀自刎，年三十三，太宗赠中书令，追封魏王。"
