    "q": "为什么赵德昭请赏之后会自刎？",
    "a": "因为太宗的「待汝自为之」不是驳回请赏，而是把高梁河之夜的事当众挑明：你要赏人，等你当了皇帝再说。这句话把一个没有发生的事实，说成了正在准备的事。德昭性谨厚、不预朝政，既没有谋逆的举动，也没有自白的余地；他若申辩，便是承认传言有据，若沉默，便是默认。底本写他退而自刎，年三十三。更深一层是结构：太宗得位无遗诏，太祖之子活着一天，就是一天的把柄，他这一死，等于替二叔把这把柄收走。",
