 "headline": "本该被召的那个皇子，一生只是个封号",
 "lead": "赵德芳，宋太祖第四子，生于汴京。开宝年间为兴元尹、山南西道节度使，一度挂贵州防御使的差遣，太祖尝有意立之而未及施行。开宝九年太祖暴崩，宋皇后在四更天命大太监王继恩出宫去召他，王继恩却在路上改了主意，直奔开封府宣召晋王赵光义；一夜之间，皇位落到了二叔手里，他这个本该被召的皇子，连宫门都没有进去。太宗即位，德芳改授同平章事，封爵如故。太平兴国二年出阁，名义上位列宰辅，实则不预政事，宗室之权一日日削下去。太平兴国四年德昭自裁、廷美远贬，德芳越发不自安，史称其忧惧成疾。太平兴国六年卒，年二十三，赠中书令，追封岐王。其死因史无明文，后世小说取其形貌，敷演出一位八贤王，其实并无其事。",
