 "headline": "把南宋内廷搅乱十年的悍后",
 "lead": "李凤娘，安阳人，父李道为庆远军节度使，家世是军将而非门阀。她少时以容色入选，乾道四年为恭王赵惇之妃；乾道七年赵惇立为太子，她随之成为太子妃，屡谗毁左右，太子不能制。淳熙十六年光宗即位，她被立为皇后，外戚李道等皆得官。她性妒而多疑，光宗畏之，宫中侧目。绍熙元年以后，她在光宗与孝宗之间传话，光宗遂不再朝重华宫，父子之隙日深；绍熙二年黄贵妃暴卒，人疑后所为，光宗由是病悸，心疾日甚。绍熙四年她专决内政，宰执不得见。绍熙五年群臣以光宗不能执丧，拥立嘉王赵扩，是为宁宗，她遂失权，随光宗退居太上皇宫。庆元六年卒，年五十六。史家以其妒悍乱政，为南宋后宫之祸；然其得立、得专，皆因光宗之病与朝中姑息，非一人之力所能致。",
