 "headline": "垂帘两年，替幼主签下一纸降表",
 "lead": "谢道清，台州临海人，父谢渠伯，祖父谢深甫为宁宗朝宰相。宝庆间她以容德入宫，历封郡夫人；嘉熙四年立为皇后。理宗一朝她以俭德闻，然外戚谢奕昌、谢奕修等皆以恩补官，谢氏一门颇盛，朝论少之。德祐元年恭帝即位，年方四岁，她以太后之尊垂帘听政，朝政决于贾似道余党，边报日急而无所措。鄂州败闻之后，朝野汹汹，她罢贾似道以谢天下，又下诏诸道勤王，而应者寥寥。德祐二年元兵至临安，她奉传国玺上表降元，宋廷遂亡，宗室多被北迁。她临朝前后不过两年，诏令多由内廷发出，外朝诸臣各怀去就。至元二十年卒于北方，年七十四。论者谓宋亡之际她不能死国；然幼主在侧、大臣皆走，降表既上，临安未遭屠戮，东南之民赖以保全。",
