   "a": "因为他的苦处是蜀中所有人的苦处。宋初平蜀之后赋役本重，茶又归官家专买，博买务一设，私贩成罪，种茶的、贩茶的一齐没了活路。他家里连茶树都没有，靠收茶转卖赚脚力钱，正是最早断炊的那一批。底本说他天生是个带头人，把所有的苦难和希望凝成一句话——我恨贫富不均，如今替你们均一均。这句话不需要识字，也不需要解释，饥民听见就懂。人不是被他动员来的，是被日子赶来的。",
