 "headline": "从乌台狱到儋州：一支笔的三次贬",
 "lead": "苏轼字子瞻，眉州眉山人。父苏洵二十七岁才发愤读书，以文章名世；母程氏亲授经史，他与弟苏辙自幼同案。嘉祐二年兄弟同榜进士，主考欧阳修读其文而惊叹，谓老夫当避路。嘉祐六年应制科入三等，签书凤翔判官，始亲民事。熙宁间他上书论新法不便，出为杭州通判，徙知密州、徐州；徐州黄河决口，他亲率军民筑堤守城，七十日水退。元丰二年，御史台以诗讥朝政劾之，下狱百三十日，赖吴充与曹太后多方营救得免，贬黄州团练副使，筑室东坡，自号东坡居士。元祐初起为翰林学士，出知杭州，浚西湖、筑长堤，杭人称为苏公堤。绍圣元年新党再起，远贬惠州，再贬儋州，居海南三年。元符三年徽宗嗣位放还，建中靖国元年卒于常州，年六十五，谥文忠。",
