   "a": "因为他惯于用技术的手段去解政治的题目。改历、治水、争地界，这些事有数据、有图纸、有是非可辨，他做得极好；边事却不然，筑城的位置、进兵的时机、粮道的远近，背后是朝廷主战主和的两股力气，不是算得准就能办成。元丰五年他在延州建议筑永乐城，城成而援绝，西夏大军一围便陷，责任自然落在他这个经略安抚使身上。他的长处是可以被差遣的才干，短处是凡有主张必据理力争，到了要人替他转圜的地方，便无人肯替他说话。",
