    "a": "因为在太后临朝的局面里，仪注就是权柄的刻度。太后用哪一座殿受册、几日一御朝、与皇帝同坐还是分坐，看起来是排场，实际上是名分所到之处；今日让一寸，明日就再进一尺。王曾援引东汉太后当国的先例，请太后与小皇帝每五日同御正殿共听政事，等于给临朝定下日子与场所，不许随意为之。尊号发册之争各让一步，也说明他争的不是意气，是可引之例。底本记他凡揽权之事都想方设法搅黄，正是这个路数。",
