   "a": "因为北宋在西夏起兵之初，没有更合适的人可派。他是馆阁出身的重臣，历知制诰、枢密副使，熟悉朝廷的兵制与诏令，论资望足以压住陕西一路；可边事要的是临阵决断，他偏偏长于谋划而短于用兵，主守不出，坐视刘平、石元孙之败不救，好水川之后朝议自然归咎于他。庆历三年他拜枢密使，台谏交章论其怯懦，仍是这笔旧账。同一个人，做词臣是上选，做边帅是错配，位置放错了，才学反而成了话柄。",
