    "同年冬天金人再度南下，各路援兵的道路已经断了。",
    "底本说，靖康之祸终不可免，此后的事只是先后。",
    "三代为将的种氏，到这一代只剩下一个名声。",
    "他的方略后来被人反复引用，当时却一行也没有行。",
    "一个朝代亡国之前，往往先把最后一个会打仗的人送走。"
