    "q": "为什么种师道一死，汴京的守御就再难支撑？",
    "a": "因为靖康年间汴京缺的不只是兵，是能把兵捏成一股的人。禁军久不习战，各路勤王兵互不统属，朝廷又在中与和之间摇摆；能同时压得住边军、又敢在御前争方略的，只有这个三世将门的老帅。他一死，西军旧部失去共主，主和的一派再无人可忌，守城之策随人而废。底本说得直白：宋失宿将，汴京之守益难，靖康之祸终不可免。他活着的时候策不得尽用，他死了之后连说策的人也没有了。",
