MR.people["song:zhangbangchang"] = {
 "headline": "三十三日楚帝：从宋臣到赐死",
 "lead": "张邦昌，字子能，永静军东光人。元符三年登进士第，此后二十余年历州县、入台省，由尚书右丞、左丞而中书侍郎，靖康初累官少宰，再进太宰兼门下侍郎。他不是以才略著称的臣子，善事上官，无赫赫之名，在朝中却一路稳升，靠的是柔顺与不与人争。靖康元年金人索三镇，他力主割地，与李纲等主战者对立；议和时他以宰相之尊出使金营，与亲王各一人同留为质。靖康二年金人废二帝，择立异姓，选中了他，册为楚帝。他不敢居正殿，退居尚书省，不敢称朕，百官多不至，在位仅三十三日。金兵退后，他迎孟太后垂帘听政，奉康王赵构即位，自请罢归。建炎元年，高宗以僭逆之罪赐其死，年四十七。论者谓其非甘心僭窃，然身为大臣不能死节，终难逃一死。",
 "points": [
  "起家：元符三年进士，历州县入台省，以柔顺善事上官一路升至少宰、太宰。",
  "转折：靖康元年力主割地，以宰相出使金营为质，被金人看作最易制的一个。",
  "落点：被册为楚帝三十三日即退位迎立赵构，仍以僭逆之罪赐死，年四十七。"
 ],
 "why": [
  {
   "q": "为什么金人择立异姓时，偏偏选中了张邦昌？",
   "a": "因为金人这时要的不是一个能治国的皇帝，是一个能签字的人。靖康二年二帝被废，赵氏宗室大批被掳北上，再立赵姓等于让宋朝原样复起，此番南下便白走一趟；而中原的赋税、和约的履行、百官的差遣，又必须有一个人出面承担。张邦昌位至太宰，资历完整，在金营为质时又表现出极度的柔顺，底本记他瘫在地上痛哭求饶，自陈是百依百顺的宋朝人。位高而易制，正是最合用的一条。他在位三十三日，不敢居正殿、不敢称朕，也正说明这个位子从一开始就是借来的。",
   "basis": {
    "type": "book",
    "text": "底本第十五章 开封保卫战"
   }
  }
 ],
 "gap": [
  "张邦昌登第之后的具体任职次序，底本未载",
  "他在金营所允诺的条件，史无明文",
  "册立仪式的具体地点与日期，底本未载"
 ],
 "quotes": []
};
