   "a": "因为他站的位置始终是「守成」这一边，而这一边在仁宗、英宗、神宗、哲宗四朝都有人要。他出自介休仕宦之家，天圣五年登进士第，与韩琦同榜，资历在朝中少有能比；行事守礼数、不走极端，党争翻覆之际既不做首倡者，也不做第一个被清算的人。庆历平贝州给他军功，熙宁争新法给他名望，元祐耆英会给他士林的推崇。底本说王安石、司马光等人死后，除了更老的文彦博之外，没有谁能超过他——年资本身就是四朝之间最硬的通行证。",
